    li = c['listen']
    P.append(dict(t='rl_listen', stage='immersion', title='Scene & listening', scene=dict(scene=c['scene'], tod=c.get('tod', 'day'), cast=[a, b]), pass1=li['pass1'], pass2=dict(tasks=li['tasks']),
     teach=teach(goal='Compreender a situação antes de ver o texto: ideia principal e depois as informações-chave.', solo=['Esconda o texto. 1ª escuta: só a ideia principal.', '2ª escuta: as informações da tarefa 2.', 'Mostre o texto só depois da 2ª escuta.'], group=['Escuta coletiva; duplas anotam as respostas antes de revelar.', 'Compare as respostas entre as duplas e só então mostre o texto.'], answers=li['answers'], extra=['Who is speaking? How do you know?', 'Which word did you catch first?'], support=['Use o botão “Slow” na 2ª escuta.', 'Pause depois de cada fala se necessário.'])))
    dg = c['dq']
